#include "BlitzCore.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
static unsigned long long hash(const void *v,size_t n){const unsigned char*p=v;unsigned long long h=14695981039346656037ull;for(size_t i=0;i<n;i++){h^=p[i];h*=1099511628211ull;}return h;}
int main(int argc,char**argv){BlitzCore c;assert(blitz_core_init(&c,1024,768,argv[1]));assert(c.path[0].x==30000&&c.path[0].y==0);assert(c.circle[0].x==5000&&c.circle[0].y==0);assert(c.circle[10].x==0&&c.circle[10].y==5000);if(argc>2){char path[4096];snprintf(path,sizeof(path),"%s/tables.bin",argv[2]);FILE*f=fopen(path,"wb");for(int table=0;table<2;table++){BlitzPoint*p=table?c.circle:c.path;for(int i=0;i<(table?40:1024);i++){unsigned v[2]={(unsigned)p[i].x,(unsigned)p[i].y};for(int j=0;j<2;j++){unsigned char b[4]={v[j]>>24,v[j]>>16,v[j]>>8,v[j]};fwrite(b,1,4,f);}}}fclose(f);}assert(c.palette[0][0]==65535&&c.palette[255][0]==0);for(int j=0;j<5;j++){unsigned frame=(unsigned[]){0,1,60,256,1023}[j];blitz_core_frame(&c,frame);blitz_core_expand(&c,100);size_t white=0;for(size_t i=0;i<1024*768;i++)if(c.indexed[i]==0)white++;printf("frame %u: %zu white pixels, indexed FNV64 %016llx\n",frame,white,hash(c.indexed,1024*768));if(argc>2){char name[4096];snprintf(name,sizeof(name),"%s/frame-%04u.ppm",argv[2],frame);FILE*f=fopen(name,"wb");fprintf(f,"P6\n1024 768\n255\n");for(size_t i=0;i<1024*768;i++){unsigned char p[3]={c.bgra[4*i+2],c.bgra[4*i+1],c.bgra[4*i]};fwrite(p,1,3,f);}fclose(f);}}blitz_core_expand(&c,0);for(size_t i=0;i<1024*768;i++){assert(c.bgra[4*i]==0&&c.bgra[4*i+1]==0&&c.bgra[4*i+2]==0);}blitz_core_destroy(&c);return 0;}
